100	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表 + 可选的本次扣款上限。
101	// Limits 缺省、为 null 或为空数组时不限制扣款。
102	type FeeBatch struct {
103		FeeBps  int             `json:"fee_bps"`
104		Intents []PaymentIntent `json:"intents"`
105		Limits  []ChargeLimit   `json:"limits,omitempty"`
106	}
