	dir := filepath.Dir(path)
	tmpName, err := stageTempFile(dir, data)
	if err != nil {
		return false, err
	}

	// O_EXCL 互斥、O_NOFOLLOW 拒绝文件位置符号链接：先占住名字再写内容，
